import{_ as a,o as s,c as i,a0 as t}from"./chunks/framework.jwovEGr5.js";const k=JSON.parse('{"title":"VitePress学习小记","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"理论学习/VitePress学习.md","filePath":"理论学习/VitePress学习.md"}'),o={name:"理论学习/VitePress学习.md"};function n(p,e,d,l,r,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="vitepress学习小记" tabindex="-1">VitePress学习小记 <a class="header-anchor" href="#vitepress学习小记" aria-label="Permalink to &quot;VitePress学习小记&quot;">​</a></h1><h2 id="vitepress介绍" tabindex="-1">VitePress介绍 <a class="header-anchor" href="#vitepress介绍" aria-label="Permalink to &quot;VitePress介绍&quot;">​</a></h2><p>VitePress是一个由Vite和Vue驱动的静态网站生成器，旨在快速构建以内容为中心的网站。它可以将用Markdown编写的内容转换为优雅的文档，生成静态HTML页面，方便部署到任何地方。（官网）</p><h2 id="我的探索" tabindex="-1">我的探索 <a class="header-anchor" href="#我的探索" aria-label="Permalink to &quot;我的探索&quot;">​</a></h2><h3 id="跳转页面" tabindex="-1">跳转页面 <a class="header-anchor" href="#跳转页面" aria-label="Permalink to &quot;跳转页面&quot;">​</a></h3><p>有时，我们希望能够用户点击跳转时，可以新打开一个页面而不会覆盖原来的页面</p><p><strong>原生语法：</strong></p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">展示名称</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">./name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){target=&quot;_blank&quot;}</span></span></code></pre></div><p>但是当我们同级未加<code>.</code>或加了后缀<code>.md</code>时，跳转会失败：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">展示名称</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">/name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){target=&quot;_blank&quot;}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">展示名称</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">./name.md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){target=&quot;_blank&quot;}</span></span></code></pre></div><p><strong>Markdown支持HTML语法，如下：</strong></p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;a href=&quot;./name&quot; target=&quot;_blank&quot; rel=&quot;noopener noreferrer&quot;&gt;展示名称&lt;/a&gt;</span></span></code></pre></div><p>同理：同级未加<code>.</code>或加了后缀<code>.md</code>时，跳转会失败：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;a href=&quot;/name&quot; target=&quot;_blank&quot; rel=&quot;noopener noreferrer&quot;&gt;展示名称&lt;/a&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;a href=&quot;./name.md&quot; target=&quot;_blank&quot; rel=&quot;noopener noreferrer&quot;&gt;展示名称&lt;/a&gt;</span></span></code></pre></div><h3 id="首页hero添加image的问题" tabindex="-1">首页hero添加image的问题 <a class="header-anchor" href="#首页hero添加image的问题" aria-label="Permalink to &quot;首页hero添加image的问题&quot;">​</a></h3><p>在Vitepress加Github托管的静态模式下，包含<code>index.md</code>文件。</p><p>其中的<code>YAML</code>语法<code>hero</code>中的部分，应该是可以通过<code>image</code>为首页添加图片。</p><p>此时出现问题：本地测试正常，而托管到Github之上后无法找到图片路径</p><h5 id="不是图片名称原因" tabindex="-1">不是图片名称原因 <a class="header-anchor" href="#不是图片名称原因" aria-label="Permalink to &quot;不是图片名称原因&quot;">​</a></h5><p>经测试，所在路径包括自己名称本身都为英文的图片，也无法正常显示</p><h5 id="应该不是哈希的原因" tabindex="-1">应该不是哈希的原因 <a class="header-anchor" href="#应该不是哈希的原因" aria-label="Permalink to &quot;应该不是哈希的原因&quot;">​</a></h5><p><strong>有关public文件夹的方法</strong></p><p>public核心特性：</p><ol><li>完全不经过Vite/Rollup编译处理</li></ol><p>文件原样复制到打包输出dist根目录，不会压缩、不会加hash后缀、不会base64内联。</p><blockquote><p>哪怕 md 里完全没有引用这个文件，打包依然会复制过去。</p></blockquote><ol start="2"><li>访问路径：必须用根绝对路径<code>/</code></li></ol><p><code>public/logo.png</code>→md/vue中写<code>/logo.png</code>访问</p><p>经尝试，public文件夹并没有解决问题</p><p><strong>避免哈希</strong></p><p>有可能只有public文件夹避免了编译处理，其子文件夹并没有</p><p>我们将图片直接放入public文件夹，发现问题也并没有解决</p><h5 id="测试过程以及猜想" tabindex="-1">测试过程以及猜想 <a class="header-anchor" href="#测试过程以及猜想" aria-label="Permalink to &quot;测试过程以及猜想&quot;">​</a></h5><p>点开开F12开发者工具中的网络选项，刷新页面观察，该文件出现了报错404</p><p>格式<code>text/html</code>不是指图片文件的格式，而是指404页面的格式</p><p>报错说明网页根本没有找到我们在首页<code>image</code>中放置的图片</p><p>回看Github仓库，路径中含有我们需要的图片，但是在发现在dist中没有该图片</p><blockquote><p>查看方法：在Actions中，点击你的deploy，其中展开的操作里面有可以下载，完成之后是一个压缩包zip，里面还有一个压缩包rar，解压缩完毕之后可以查看到，我们需要的照片并没有被读取</p></blockquote><p>Github根本没有读取，这就相当奇怪</p><p>在本地进行测试的时候，所有路径都是直接进行读取的，因此首页图片可以正常显示；而托管之后图片路径缺失，因此无法正常显示</p><h5 id="其他实现方法" tabindex="-1">其他实现方法 <a class="header-anchor" href="#其他实现方法" aria-label="Permalink to &quot;其他实现方法&quot;">​</a></h5><p>或许我们可以用普通引用图片+CSS的方法解决</p><h3 id="md添加图片" tabindex="-1"><code>.md</code>添加图片 <a class="header-anchor" href="#md添加图片" aria-label="Permalink to &quot;\`.md\`添加图片&quot;">​</a></h3><blockquote><p>相对路径方法</p></blockquote><h5 id="文件夹管理" tabindex="-1">文件夹管理 <a class="header-anchor" href="#文件夹管理" aria-label="Permalink to &quot;文件夹管理&quot;">​</a></h5><p>文件越做越多，因此我们需要管理我们的图片文件夹，以防越来越乱</p><p>示例：在你的<code>docs</code>文件夹内部添加<code>img</code>文件夹（代表图片）</p><p>此时你的目录结构参考如下</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目根目录</span></span>
<span class="line"><span>├─ docs/</span></span>
<span class="line"><span>│  ├─ img/        # 专门存放文章图片</span></span>
<span class="line"><span>│  │  ├─ 1.png</span></span>
<span class="line"><span>│  │  └─ 2.jpg</span></span>
<span class="line"><span>│  ├─ articles/      # 你的文章md文件夹</span></span>
<span class="line"><span>│  │  └─ 1.md</span></span>
<span class="line"><span>│  └─ index.md       # 首页</span></span>
<span class="line"><span>└─ package.json</span></span></code></pre></div><h5 id="添加图片" tabindex="-1">添加图片 <a class="header-anchor" href="#添加图片" aria-label="Permalink to &quot;添加图片&quot;">​</a></h5><p>复习：Markdown的图片添加为<code>![图片替代文字](路径)</code></p><p>路径规则和HTML是一样的，<code>../</code>代表父级，<code>./</code>代表同级，<code>/</code>代表子级</p><p>根据当前<code>.md</code>文件位置反推图片位置即可</p><p>我们只需要先“到达”共同文件夹，然后一级一级往下找到我们的图片文件</p><p>以上文为例，<code>1.md</code>文件内添加<code>1.png</code>文件</p><ol><li><p>我们知道他们的共同文件夹是<code>docs</code>，所以先用<code>../</code>从<code>1.md</code>所在文件夹<code>articles</code>进入<code>docs</code></p></li><li><p>下一级文件<code>img</code>，再下一级为<code>1.png</code></p></li></ol><p>所以我们的路径就有了：<code>../img/1.png</code></p><h3 id="图片格式设置" tabindex="-1">图片格式设置 <a class="header-anchor" href="#图片格式设置" aria-label="Permalink to &quot;图片格式设置&quot;">​</a></h3><p>MarkDown语法本身不支持图片格式的设置，但是在VitePress当中是可以进行修改的</p><p>原生样式：<code>![图片替代文字](路径)</code></p><p>我们在后方添加<code>{}</code>，内部加上我们需要的格式</p><p>例如：<code>![图片替代文字](路径){width=400px}</code>，这样就设置了图片的宽度</p><blockquote><p>暂时只发现了width的用法，连height都用不了</p></blockquote><h2 id="vitepress其他" tabindex="-1">VitePress其他 <a class="header-anchor" href="#vitepress其他" aria-label="Permalink to &quot;VitePress其他&quot;">​</a></h2><p>VitePress支持直接在index.md里写完整Vue模板，关闭默认首页布局，用纯Vue+CSS写整个仪表盘页面，不用修改.vitepress/theme主题文件。</p><p>details: Lorem ipsum dolor sit amet, consectetur adipiscing elit是VitePress模板自带的示例占位描述，是无实义填充文本。</p>`,66)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
